mapper.update:
UPDATE knowledge_base kb
SET kb.doc_count = (
        SELECT COUNT(*) FROM kb_document d
        WHERE d.kb_id = kb.id AND d.deleted = 0 AND d.status = 'INDEXED'
    ),
    kb.chunk_count = (
        SELECT COUNT(*) FROM kb_chunk c WHERE c.kb_id = kb.id
    ),
    kb.update_time = NOW()
WHERE kb.id = #{id}
